import assert from 'node:assert/strict';
import {mkdtempSync,writeFileSync,readFileSync,rmSync,existsSync} from 'node:fs';
import {join} from 'node:path';
import {tmpdir} from 'node:os';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {codexTool,defineAgentTool,runSupervisedTask} from '/workspace/research-delivery/packages/agent-tools/src/index.js';
import {createSupervisedObservation} from '/workspace/research-delivery/packages/agent-tools/src/observation.js';
import {createRunTraceWriter,verifyTraceFile,readTraces} from '/workspace/research-delivery/packages/agent-tools/src/run-trace.js';
import {runAgentToolsEval} from '/workspace/research-delivery/packages/agent-tools/src/experiment/index.js';
import {mapBackendOrderToAgentTask,makeBackendWorkOrder,defineBackendObjective,BackendContextSchema} from '/workspace/research-delivery/packages/agentic-system/src/index.js';
const root=mkdtempSync(join(tmpdir(),'research-cli-seam-')), repo=join(root,'repo');
const {mkdirSync}=await import('node:fs');mkdirSync(repo);
const fake='/workspace/research-delivery/packages/agent-tools/test/fixtures/fake-agent.mjs';
function git(...args){const r=spawnSync('git',args,{cwd:repo,encoding:'utf8',env:{...process.env,GIT_CONFIG_NOSYSTEM:'1',GIT_AUTHOR_NAME:'research',GIT_AUTHOR_EMAIL:'research@localhost.invalid',GIT_COMMITTER_NAME:'research',GIT_COMMITTER_EMAIL:'research@localhost.invalid'}});assert.equal(r.status,0,r.stderr);return r.stdout.trim();}
const snap=()=>({head:git('rev-parse','HEAD'),refs:git('for-each-ref','--format=%(refname) %(objectname)','refs/heads'),status:git('status','--porcelain','--untracked-files=all')});
try{
 git('init','-q','-b','main');
 writeFileSync(join(repo,'sum.mjs'),'export const sum=(a,b)=>a-b;\n');
 writeFileSync(join(repo,'sum.test.mjs'),'import {sum} from "./sum.mjs";import assert from "node:assert/strict";assert.equal(sum(2,3),5);\n');
 git('add','-A');git('-c','commit.gpgsign=false','commit','-qm','fixture');const base=git('rev-parse','HEAD');
 const before=snap(), recoveryDir=join(root,'recovery'),record=join(root,'record.json'),traceDir=join(root,'traces');
 const order=makeBackendWorkOrder(defineBackendObjective({id:'probe-objective',task:'Fix sum to add',repository:{ref:'repo://research',revision:base},requiredFiles:['sum.mjs']}));
 const context=BackendContextSchema.parse({repository:{ref:'repo://research',revision:base},files:[{path:'sum.mjs',content:'export const sum=(a,b)=>a-b;',sourceRef:'fixture'}]});
 const task=mapBackendOrderToAgentTask(order,context,{repositoryRoot:repo,verifications:[{name:'typecheck',command:process.execPath,args:['--test','sum.test.mjs'],timeoutMs:5000,claim:'backend.typecheck'},{name:'tests',command:process.execPath,args:['--test','sum.test.mjs'],timeoutMs:5000,claim:'backend.tests'}]});
 const env={FAKE_AGENT_SCENARIO:'FIX_FIRST',FAKE_AGENT_RECORD:record};
 const observer=createSupervisedObservation({tool:defineAgentTool(codexTool,{command:process.execPath,prefixArgs:[fake]}),arm:'SMOKE',taskId:task.id,writer:createRunTraceWriter({dir:traceDir,env}),env});
 let handleDuring=false; let handleAtInvocation=false;
 const opts={tool:defineAgentTool(codexTool,{command:process.execPath,prefixArgs:[fake]}),task,recoveryDir,onHandleWrite:async handle=>{if(handle.status==='RUNNING')handleDuring=existsSync(join(recoveryDir,'handle.json'));},model:'research-model',permissionProfile:'FULL_AUTO',maxAttempts:2,timeoutMs:5000,env,eventSinks:observer.eventSinks,tracer:observer.tracer,invocationObserver:async x=>{handleAtInvocation=existsSync(join(recoveryDir,'handle.json'));await observer.invocationObserver(x);}};
 const result=await runSupervisedTask(opts);assert.equal(result.status,'ACCEPTED');assert.ok(handleDuring);assert.ok(existsSync(join(recoveryDir,'handle.json')));assert.deepEqual(snap(),before);
 const records=JSON.parse(readFileSync(record,'utf8'));assert.equal(records.length,1);assert.ok(records[0].argv.includes('danger-full-access'));assert.ok(records[0].argv.includes('research-model'));
 await observer.finalize(result);const traces=verifyTraceFile(join(traceDir,'traces.jsonl'));assert.equal(traces.length,1);assert.equal(traces[0].arm,'SMOKE');assert.deepEqual(readTraces(traceDir),traces);
 let secondCode;try{await runSupervisedTask(opts);}catch(e){secondCode=e.code;}assert.equal(secondCode,'HANDLE_CURRENT');assert.equal(JSON.parse(readFileSync(record,'utf8')).length,1);
 const corrupt=join(root,'corrupt.jsonl');writeFileSync(corrupt,readFileSync(join(traceDir,'traces.jsonl'),'utf8').replace('SMOKE','OTHER'));assert.throws(()=>verifyTraceFile(corrupt),/TRACE_CHAIN_BROKEN/);
 const evalResult=await runAgentToolsEval({tools:['codex'],command:fake,tasks:['bug-sum'],out:join(root,'eval'),fakeScenario:'FIX_FIRST',factors:{permissionProfile:'FULL_AUTO',timeoutMs:5000},model:'research-model'});
 const run=evalResult.runs.codex;assert.ok(run,'eval run registered');
 const output={classification:'EXECUTED_RESEARCH_SEAM_PROBE_NOT_PRODUCT_FEATURE',runtime:process.version,sourceSha:'26b1dbe2e15fce54e6d9d7b2cfda15acf260b855',supervisor:{status:result.status,candidateSha:result.acceptedSha,argv:records[0].argv,handleDuring,handleAtInvocation,handleAfter:true,secondCode,secondDispatches:0,sourceUnchanged:true},trace:{records:traces.length,arm:traces[0].arm,chainVerified:true,corruptionRejected:true},eval:{registration:run.registration,attempts:run.attempts.map(a=>({arm:a.arm,taskId:a.taskId,status:a.status}))},limitations:'Direct delivered mapBackendOrderToAgentTask/runSupervisedTask/eval/observation seams. Does not execute the future deliver manifest, CLI eval/smoke or Application recovery forwarding; Worker focused tests must call those public subjects.'};
 writeFileSync('/workspace/research-plans/cli-seam-probe.result.json',JSON.stringify(output,null,2)+'\n');console.log(JSON.stringify(output));
} finally {rmSync(root,{recursive:true,force:true});}

